/bin/bash -lc "cat > src/quoted_env_values.ts <<'EOF'
export function parseEnv(text: string): Record<string, string> {
  const result: Record<string, string> = Object.create(null);
  const escapes: Record<string, string> = {
    n: \"\\n\", r: \"\\r\", t: \"\\t\", \"\\\\\": \"\\\\\", '\"': '\"',
  };
  for (let line of text.split(/\\r?\\n/)) {
    line = line.trim();
    if ("'!line || line.startsWith("#")) continue;
    line = line.replace(/''^export'"\\s+/, \"\");
    const match = /"'^([A-Za-z_][A-Za-z0-9_]*)'"\\s*=\\s*(.*)"'$(?!['"\\s\\S])/.exec(line);
    if ("'!match) throw new Error("invalid assignment");
    const raw = match[2];
    const quote = raw[0];
    if (quote !== '"'\"' && quote "'!== "'"'\") {
      result[match[1]] = raw.split(\"#\")[0].trim();
      continue;
    }
    let value = \"\";
    let index = 1;
    for (; index < raw.length && raw[index] "'!== quote; index++) {
      const character = raw[index];
      if (quote === '"'\"' && character === \"\\\\\") {
        const escaped = raw[++index];
        if ("'!Object.hasOwn(escapes, escaped)) throw new Error("invalid escape");
        value += escapes[escaped];
      } else {
        value += character;
      }
    }
    if (index === raw.length) throw new Error("unterminated quote");
    const remainder = raw.slice(index + 1).trim();
    if (remainder && !remainder.startsWith("#")) throw new Error("invalid assignment");
    result[match[1]] = value;
  }
  return result;
}
EOF
cat > tests/quoted_env_values.test.mjs <<'"'EOF'
import test from \"node:test\";
import assert from \"node:assert/strict\";
import { parseEnv as domainParseEnv } from \"../src/quoted_env_values.ts\";
import { parseEnv as apiParseEnv } from \"../src/api.ts\";

for (const [name, parseEnv] of [[\"domain\", domainParseEnv], [\"api\", apiParseEnv]]) {
  test("'`${name}: assignments, comments, whitespace and duplicates`, () => {
    const input = "'"\\r\\n # comment\\r\\n export A = first # comment\\r\\nA= last  \\r\\n_empty=\\r\\nB=before#after\\r\\n__proto__=safe\\r\\n\";
    assert.deepEqual({ ...parseEnv(input) }, {
      A: \"last\", _empty: \"\", B: \"before\", [\"__proto__\"]: \"safe\",
    });
  });

  test("'`${name}: quoted content and double escapes`, () => {
    const input = String.raw`A="  hello # world  " # comment
B='"'  literal \\n # \" text  '
C=\"\\n\\r\\t\\\\\\\"\"
D=''
E=\"\"#comment
F='backslash\\'
G=\"first\"
G='last'"'`;
    assert.deepEqual({ ...parseEnv(input) }, {
      A: "  hello # world  ", B: String.raw`  literal '"\\n # \" text  "'`,
      C: "'"\\n\\r\\t\\\\\\\"\", D: \"\", E: \"\", F: \"backslash\\\\\", G: \"last\",
    });
  });

  test("'`${name}: rejects malformed assignments and quoted values`, () => {
    for (const input of [
      "missing", "=value", "1KEY=value", "A-B=value", "A B=value", "export A",
      '"'A=\"missing', \"A='missing\", 'A=\"wrong\\'',
      'A=\"ok\" trailing', \"A='ok' trailing\", 'A=\"ok\"\"',
      String.raw"'`A="bad'"\\q\""'`, String.raw`A="bad'"\\'\""'`, '"'A=\"dangling\\\\',
      'A=\"line\\nbreak\"',
    ]) {
      assert.throws(() => parseEnv(input), Error, input);
    }
  });
}
EOF
node --test tests/*.test.mjs"
